--toggle float with specific size and centered
hl.bind(mainMod .. " + T", function()
	hl.dispatch(hl.dsp.window.float({ action = "toggle" }))

	local win = hl.get_active_window()
	if win and win.floating then
		hl.dispatch(hl.dsp.window.resize({ x = 1000, y = 700, relative = false, window = "activewindow" }))
		hl.dispatch(hl.dsp.window.center())
	end
end)

hl.bind(mainMod .. " + O", hl.dsp.exec_cmd("~/.local/bin/window-pop"))
hl.bind(mainMod .. " + CTRL + F", hl.dsp.exec_cmd("~/.local/bin/tiled-fullscreen"))

--toggle window transparency
hl.bind(mainMod .. " + BACKSPACE", hl.dsp.exec_cmd("~/.local/bin/transparency-toggle"))

-- for fullscreen apps with waybar visible
hl.bind(mainMod .. " + F", function()
	hl.dispatch(hl.dsp.window.fullscreen({ mode = "maximized", action = "toggle" }))
end)
-- for absolute fullscreen
hl.bind(mainMod .. " + ALT + F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
	local key = i % 10 -- 10 maps to key 0
	hl.bind(mainMod .. " + " .. key, hl.dsp.focus({ workspace = i }))
	hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
	hl.bind(mainMod .. " + ALT + " .. key, hl.dsp.window.move({ workspace = tostring(i), follow = false }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S", hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + CTRL + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up", hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

--move windows inside one workspace move left, right, up, down
hl.bind(mainMod .. " + SHIFT + LEFT", hl.dsp.window.move({ direction = "left" }))
hl.bind(mainMod .. " + SHIFT + RIGHT", hl.dsp.window.move({ direction = "right" }))
hl.bind(mainMod .. " + SHIFT + UP", hl.dsp.window.move({ direction = "up" }))
hl.bind(mainMod .. " + SHIFT + DOWN", hl.dsp.window.move({ direction = "down" }))

--resizing windows
local step = 50
hl.bind(mainMod .. " + CTRL + LEFT", hl.dsp.window.resize({ x = -step, y = 0, relative = true }), { repeating = true })
hl.bind(mainMod .. " + CTRL + RIGHT", hl.dsp.window.resize({ x = step, y = 0, relative = true }), { repeating = true })
hl.bind(mainMod .. " + CTRL + UP", hl.dsp.window.resize({ x = 0, y = -step, relative = true }), { repeating = true })
hl.bind(mainMod .. " + CTRL + DOWN", hl.dsp.window.resize({ x = 0, y = step, relative = true }), { repeating = true })

